svg.metadata:
flowchart TB
  A["init / 发送前检查"]
  B{"已有可用会话？"}
  C["等待已在进行的握手<br/>沿用它的成功或失败结果"]
  D["本地生成 SM2 密钥对；只 POST 公钥"]
  E["服务端校验并登记公钥；返回编号、公钥、预算和 TTL"]
  F["客户端验证响应；检查是否取消或已过期"]
  G["返回成功；ready() 为 true"]
  H["返回失败；不发布半完成状态"]
  A --> B
  B -->|"是"| G
  B -->|"否；已有握手"| C
  B -->|"否；尚无握手"| D
  D --> E
  E --> F
  E -->|"登记拒绝 / 超额"| H
  F -->|"全部通过"| G
  D -->|"生成 / 网络失败"| H
  F -->|"无效 / 取消 / 超时"| H
  classDef default fill:#edf3ff,stroke:#476aab,color:#172b4d,stroke-width:1.5px;
  classDef good fill:#e9f6ef,stroke:#28734e,color:#17452f,stroke-width:1.5px;
  classDef stop fill:#fff0f0,stroke:#af4040,color:#742b2b,stroke-width:1.5px;
  classDef pending fill:#fff6df,stroke:#a07827,color:#654b18,stroke-width:1.5px;
  class G good;
  class H stop;
  class C pending;
